c=torch.tensor(np.random.rand(N).astype(np.float32)); xi=torch.tensor(np.random.randn(N,2).astype(np.float32))
cn=c.numpy()
def modeidx(a):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); return np.round((ang-67.63*cn+0.18)/45).astype(int)%8
@torch.no_grad()
def dec(M=None,d=None,K0=0,K1=11):
    x=xi.clone()
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.1.act",),count=False)
        m=((a["blocks.1.act"]@w+b>0)&(K0<=k<K1)).float()[:,None]
        add=torch.zeros_like(v)
        if M is not None: add=add+x@torch.tensor(M,dtype=torch.float32).T
        if d is not None: add=add+torch.tensor(d,dtype=torch.float32)
        v=v+m*add; x=x-v/20
    return x.numpy()
