import numpy as np, torch, model
net = model.load()
det=torch.tensor(np.load('contrast_c2_out_act_k8.npy')); db=-43.0443
J=torch.tensor([[0.,-1.],[1.,0.]])
tr=np.load('track.npy'); 
def track(c): return np.interp(c, tr[::-1,0], tr[::-1,1])
def dec(X,c,alpha=0.,sgn=1,klo=0,khi=9):
    x=torch.tensor(X); c=torch.tensor(c,dtype=torch.float32); model._count(len(X))
    with torch.no_grad():
        for k in range(20):
            t=torch.full((len(x),),1-k/20)
            v,a=net.velocity(x,t,c,("out_act",),count=False)
            if alpha and klo<=k<khi:
                f=((a["out_act"]@det+db)>0).float()[:,None]
                v=v - sgn*alpha*f*(x@J.T)
            x=x-v/20
    return x.numpy()
rng=np.random.default_rng(5); N=6000
X=rng.standard_normal((N,2)).astype(np.float32); C=rng.random(N).astype(np.float32)
def lab(o):
    ang=np.degrees(np.arctan2(o[:,1],o[:,0])); r=np.linalg.norm(o,axis=1); T=track(C)
    d=lambda off: (np.abs((ang-T-off+180)%360-180)<20)&(r>2)
    return d(0), d(-90)|d(180)|d(90), r
