net = model.load()
w=torch.tensor(np.load('contrast_c4_blocks.2.fc1_k16.npy'))
def run(z,c,thr,lo,hi,mode,g):
    x=z.clone(); fired=torch.zeros(len(z),dtype=torch.bool)
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,A=net.velocity(x,t,c,("blocks.2.fc1",),count=False)
        if lo<=k<hi and g!=0:
            f=(A["blocks.2.fc1"]@w>thr); fired|=f
            if mode=='d0': add=torch.tensor([-g,0.])[None].expand_as(x)
            elif mode=='rad': add=-g*x
            v=v+f[:,None].float()*add
        x=x-v/20
    return x,fired
