import numpy as np, torch, model
net = model.load()
W=torch.tensor(np.load('c4_mydet.npy')); B=float(np.load('c4_mydetb.npy')[0])
J=torch.tensor([[0.,-1.],[1.,0.]])
def run(xi,c,beta=0,thr=0.,lo=12,hi=17,sign=1):
    x=xi.clone(); nf=0
    for k in range(20):
        t=torch.full((x.shape[0],),1-k/20)
        v,a=net.velocity(x,t,c,("out_act",),count=False)
        if beta and lo<=k<hi:
            f=((a["out_act"]@W+B)>thr).float()[:,None]
            v=v+f*(-beta*sign*(x@J.T))
        x=x-v/20
    return x
def ang(a): return np.degrees(np.arctan2(a[:,1],a[:,0]))
def dd(a,c):
    tr=(167+90*c+180)%360-180
    return (ang(a)-tr+180)%360-180
